// Validate first: an empty or malformed contact_id must match NO client row (a comparison with '' would match every row whose column is blank).
const raw = String($('Trigger').first().json.contact_id || '').trim();
const ok = /^(tg:\d{1,20}|wa:\+\d{1,20})$/.test(raw);
const formula = ok
  ? (raw.startsWith('tg:') ? "{telegram_chat_id}='" + raw.slice(3) + "'" : "{phone}='" + raw.slice(3) + "'")
  : "{client_id}='__no_such_client__'";
return [{ json: { formula } }];

// Settings are checked before anything is written: the event goes into Settings.calendar_id.
const s = ($('Settings').first().json || {}).fields;
if (!s) throw new Error('confirm_booking: the Settings table has no row');
if (typeof s.calendar_id !== 'string' || !s.calendar_id.trim()) throw new Error('confirm_booking: Settings.calendar_id is missing');
if (typeof s.timezone !== 'string' || !s.timezone.trim() || !DateTime.now().setZone(s.timezone).isValid) throw new Error('confirm_booking: Settings.timezone is missing or not a valid IANA zone, got ' + JSON.stringify(s.timezone));
const c = $('Client').first().json || {};   // the whole record: c.id is the Clients record id
const cid = (c.fields || {}).client_id;
if (!c.id || !cid) return [{ json: { action: 'reject', verdict: 'NO_PENDING', appt_id: '' } }];
// rec_id is the Appointments record id (for the updates), the rest are the columns
const appts = $('Appointments').all().map(i => ({ ...((i.json || {}).fields || {}), rec_id: (i.json || {}).id })).filter(a => a.appt_id && a.client_id === cid);
const services = $('Services').all().map(i => (i.json || {}).fields || {});
const now = DateTime.utc();
const ms = (iso) => DateTime.fromISO(String(iso || '')).toMillis();
const live = (a) => ['booked', 'reminded', 'confirmed'].includes(a.status);
const pending = appts.filter(a => a.status === 'pending').sort((a, b) => String(b.pending_expires_at || '').localeCompare(String(a.pending_expires_at || '')))[0];
if (!pending) {
  // No proposal waiting: a repeated YES for a visit that is already booked is ALREADY_BOOKED with that visit's id.
  const future = appts.filter(a => live(a) && ms(a.start_iso) > now.toMillis()).sort((a, b) => ms(a.start_iso) - ms(b.start_iso))[0];
  return [{ json: { action: 'reject', verdict: future ? 'ALREADY_BOOKED ' + future.appt_id : 'NO_PENDING', appt_id: future ? future.appt_id : '' } }];
}
// A pending row that starts exactly when an already booked visit of this client starts is a stray (a Create Appt retry in
// propose_booking can leave one): cancel it and answer with the booked visit, instead of finding the slot taken by the client's own event.
const twin = appts.find(a => live(a) && ms(a.start_iso) === ms(pending.start_iso));
if (twin) return [{ json: { action: 'stray', rec_id: pending.rec_id, verdict: 'ALREADY_BOOKED ' + twin.appt_id, appt_id: twin.appt_id } }];
const exp =DateTime.fromISO(String(pending.pending_expires_at || ''));
if (!exp.isValid || exp < now) return [{ json: { action: 'expire', rec_id: pending.rec_id, appt_id: pending.appt_id } }];
const start = DateTime.fromISO(String(pending.start_iso || '')), end = DateTime.fromISO(String(pending.end_iso || ''));
if (!start.isValid || !end.isValid || end <= start) throw new Error('confirm_booking: pending appointment ' + pending.appt_id + ' has an unreadable start_iso/end_iso');
if (!/^[A-Za-z0-9-]{1,64}$/.test(String(pending.appt_id))) throw new Error('confirm_booking: unexpected appt_id ' + JSON.stringify(String(pending.appt_id).slice(0, 80)) + ' in Appointments record ' + pending.rec_id);
// The Google event id is derived from appt_id, so the same booking always gets the same event id: Google refuses a second insert
// with that id (409), and a retried or concurrent Create Event cannot make a second event. Google ids are base32hex (0-9a-v),
// 5-1024 characters: 'appt' + the hex of the appt_id's ASCII bytes (tests/lib/n8n.sh appt_event_id computes the same).
const event_id = 'appt' + [...pending.appt_id].map(ch => ch.charCodeAt(0).toString(16).padStart(2, '0')).join('');
const svc = services.find(x => x.service_id === pending.service_id) || {};
const hadVisits = appts.some(a => ['booked', 'reminded', 'confirmed', 'done'].includes(a.status));
return [{ json: { action: 'check', rec_id: pending.rec_id, appt_id: pending.appt_id, start_iso: pending.start_iso, end_iso: pending.end_iso,
  service_id: pending.service_id, service_name: svc.name || pending.service_id, replaces_appt_id: pending.replaces_appt_id || '', first_visit: !hadVisits, event_id } }];

// Taken = some busy interval really overlaps [start, end). The empty {} item of alwaysOutputData is dropped; a busy item that does not parse is not "free": throw.
const d = $('Decide').first().json;
const s = DateTime.fromISO(d.start_iso), e = DateTime.fromISO(d.end_iso);
const taken = $input.all().map(i => i.json || {}).filter(b => b.start || b.end).some(b => {
  const bs = DateTime.fromISO(String(b.start)), be = DateTime.fromISO(String(b.end));
  if (!bs.isValid || !be.isValid) throw new Error('confirm_booking: unreadable busy interval from Google Calendar: ' + JSON.stringify(b));
  return bs < e && be > s;
});
return [{ json: { taken } }];

// own = this booking's event (id derived from appt_id) is in the calendar. The empty {} item of alwaysOutputData has no id.
const d = $('Decide').first().json;
const own = $input.all().some(i => (i.json || {}).id === d.event_id);
// Coming from a failed Create Event, no own event means the create really failed (not a duplicate): fail the tool (-> WF-6).
if (!own && $('Create Event').isExecuted) {
  let why = '';
  try { why = String((($('Create Event').all(1)[0] || {}).json || {}).error || ''); } catch (e) { why = ''; }
  throw new Error('confirm_booking: Create Event failed for ' + d.appt_id + ' and no event ' + d.event_id + ' is in the calendar' + (why ? ': ' + why : ''));
}
return [{ json: { own } }];
